'use client'

import { FormEvent, useState } from 'react'
import { ArrowUpRight } from 'lucide-react'
export function ContactForm() { const [sent, setSent] = useState(false); function submit(e: FormEvent) { e.preventDefault(); setSent(true) } return <form onSubmit={submit} className="flex flex-col gap-5">{sent ? <div className="border border-[var(--gold)] bg-[#fbfaf7] p-6"><p className="font-serif text-2xl text-[var(--navy)]">Recebemos sua mensagem.</p><p className="mt-2 text-sm leading-6 text-[var(--muted)]">Nossa equipe entrará em contato em breve.</p></div> : <><div className="grid gap-5 sm:grid-cols-2"><label className="flex flex-col gap-2 text-xs font-semibold uppercase tracking-[.12em] text-[var(--muted)]">Nome<input required className="border-b border-[var(--line)] bg-transparent py-3 text-base font-normal normal-case tracking-normal text-[var(--foreground)] outline-none focus:border-[var(--gold)]" /></label><label className="flex flex-col gap-2 text-xs font-semibold uppercase tracking-[.12em] text-[var(--muted)]">E-mail<input type="email" required className="border-b border-[var(--line)] bg-transparent py-3 text-base font-normal normal-case tracking-normal text-[var(--foreground)] outline-none focus:border-[var(--gold)]" /></label></div><label className="flex flex-col gap-2 text-xs font-semibold uppercase tracking-[.12em] text-[var(--muted)]">Assunto<input required className="border-b border-[var(--line)] bg-transparent py-3 text-base font-normal normal-case tracking-normal text-[var(--foreground)] outline-none focus:border-[var(--gold)]" /></label><label className="flex flex-col gap-2 text-xs font-semibold uppercase tracking-[.12em] text-[var(--muted)]">Mensagem<textarea required rows={4} className="resize-none border-b border-[var(--line)] bg-transparent py-3 text-base font-normal normal-case tracking-normal text-[var(--foreground)] outline-none focus:border-[var(--gold)]" /></label><button className="flex w-fit items-center gap-2 bg-[var(--navy)] px-5 py-4 text-xs font-semibold uppercase tracking-[.13em] text-[#f6f5f2] transition-colors hover:bg-[var(--gold)]">Enviar mensagem <ArrowUpRight size={16} /></button></>}</form> }
